// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DeployTarget) predicate.DeployTarget {
	return predicate.DeployTarget(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DeployTarget) predicate.DeployTarget {
	return predicate.DeployTarget(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DeployTarget) predicate.DeployTarget {
	return predicate.DeployTarget(sql.NotPredicates(p))
}
